import java.io.*;
import java.util.*;

public class Ciclovias {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int[] eu = new int[M];
        int[] ev = new int[M];
        int[] deg = new int[N + 1];
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            eu[i] = u;
            ev[i] = v;
            deg[u]++;
            deg[v]++;
        }

        int[][] adj = new int[N + 1][];
        for (int i = 1; i <= N; i++) {
            adj[i] = new int[deg[i]];
        }
        int[] pos = new int[N + 1];
        for (int i = 0; i < M; i++) {
            int u = eu[i], v = ev[i];
            adj[u][pos[u]++] = v;
            adj[v][pos[v]++] = u;
        }
        for (int i = 1; i <= N; i++) {
            Arrays.sort(adj[i]);
        }

        int[][] dp = new int[N + 1][];
        for (int i = 1; i <= N; i++) {
            dp[i] = new int[adj[i].length];
        }

        final int INF_NEG = -1000000000;
        int[] bestOut = new int[N + 1];
        Arrays.fill(bestOut, INF_NEG);

        int[] bucketHead = new int[N + 2];
        Arrays.fill(bucketHead, -1);
        int maxUpdates = M;
        int[] bucketNext = new int[maxUpdates + 1];
        int[] bucketTarget = new int[maxUpdates + 1];
        int[] bucketValue = new int[maxUpdates + 1];
        int bucketCnt = 0;

        for (int v = N; v >= 1; v--) {
            int[] neigh = adj[v];
            int len = neigh.length;
            int[] dpv = dp[v];

            // Step 1: compute G(v, u) for u < v
            for (int i = 0; i < len; i++) {
                int u = neigh[i];
                if (u < v) {
                    int base = bestOut[u];
                    int A = (base == INF_NEG) ? 0 : base + 1;
                    dpv[i] = A;
                    // schedule update to bestOut[v] at step u
                    bucketNext[bucketCnt] = bucketHead[u];
                    bucketTarget[bucketCnt] = v;
                    bucketValue[bucketCnt] = A;
                    bucketHead[u] = bucketCnt;
                    bucketCnt++;
                }
            }

            // Step 2: compute G(u, v) for u < v
            int max = INF_NEG;
            for (int i = len - 1; i >= 0; i--) {
                int u = neigh[i];
                if (u < v) {
                    int B = (max == INF_NEG) ? 0 : max + 1;
                    int idx = Arrays.binarySearch(adj[u], v);
                    dp[u][idx] = B;
                    if (B > bestOut[u]) bestOut[u] = B;
                }
                if (dpv[i] > max) max = dpv[i];
            }

            // Step 3: apply scheduled updates for step v
            for (int e = bucketHead[v]; e != -1; e = bucketNext[e]) {
                int target = bucketTarget[e];
                int val = bucketValue[e];
                if (val > bestOut[target]) bestOut[target] = val;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int c = 1; c <= N; c++) {
            int ans = 1;
            int[] neigh = adj[c];
            int[] dpc = dp[c];
            for (int i = 0; i < neigh.length; i++) {
                int val = 2 + dpc[i];
                if (val > ans) ans = val;
            }
            sb.append(ans);
            if (c < N) sb.append(' ');
        }
        System.out.println(sb.toString());
    }
}
